mapper.select:
SELECT a.store_id, COALESCE(a.seller_sku, '') AS seller_sku, '' AS country,
       YEAR(a.alloc_date) * 100 + MONTH(a.alloc_date) AS period, a.item_type, SUM(a.amount_base) AS amount
FROM ecom_fee_allocation a
WHERE a.alloc_date >= #{begin} AND a.alloc_date <= #{end}
AND a.store_id = #{storeId}
GROUP BY a.store_id, COALESCE(a.seller_sku, ''), YEAR(a.alloc_date) * 100 + MONTH(a.alloc_date), a.item_type
UNION ALL

SELECT a.store_id, COALESCE(a.seller_sku, '') AS seller_sku, '' AS country,
       YEAR(a.alloc_date) * 100 + MONTH(a.alloc_date) AS period, a.item_type, SUM(a.amount_base) AS amount
FROM ecom_owh_fee_alloc a
WHERE a.order_id IS NULL AND a.alloc_date >= #{begin} AND a.alloc_date <= #{end}
AND a.store_id = #{storeId}
GROUP BY a.store_id, COALESCE(a.seller_sku, ''), YEAR(a.alloc_date) * 100 + MONTH(a.alloc_date), a.item_type
